"""Low level user interaction functions for Move Image window"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.miscellaneous.decorators import log_decorator
from interops.libraries.xvi.interactions.common_objects_ops import get_text

class MoveImageOps:
    '''
    Move Image handler
    '''
    def __init__(self):
        squishtest.waitForObjectExists(Xvi_MainPage.move_Image_Window)

    @property
    def from_patient(self):
        self._from_patient = get_text(Xvi_MainPage.move_Image_From_Current_Patient_Label)
        return self._from_patient

    @property
    def from_treatment(self):
        self._from_treatment = get_text(Xvi_MainPage.move_Image_From_Current_Treatment_Label)
        return self._from_treatment

    @property
    def from_field(self):
        self._from_field = get_text(Xvi_MainPage.move_Image_From_Current_Field_Label)
        return self._from_field

    @property
    def from_image(self):
        self._from_image = get_text(Xvi_MainPage.move_Image_From_Current_Image_Label)
        return self._from_image

    @property
    def to_patient(self):
        self._to_patient = get_text(Xvi_MainPage.move_Image_To_Patient_List)
        return self._to_patient

    @property
    def to_treatment(self):
        self._to_treatment = get_text(Xvi_MainPage.move_Image_To_Treatment_List)
        return self._to_treatment

    @property
    def to_field(self):
        self._to_field = get_text(Xvi_MainPage.move_Image_To_Filed_List)
        return self._to_field

    @property
    def show_inactive_patients(self):
        self._show_inactive_patients = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_patients_CheckBox).checked
        return self._show_inactive_patients

    @show_inactive_patients.setter
    def show_inactive_patients(self, value):
        isInactiveChecked = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_patients_CheckBox).checked
        if isInactiveChecked != value:
            common.left_click_object(Xvi_MainPage.move_Image_To_Show_inactive_patients_CheckBox)
        self._show_inactive_patients = value

    @property
    def show_inactive_treatments(self):
        self._show_inactive_treatments = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_treatments_CheckBox).checked
        return self._show_inactive_treatments

    @show_inactive_treatments.setter
    def show_inactive_treatments(self, value):
        isInactiveChecked = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_treatments_CheckBox).checked
        if isInactiveChecked != value:
            common.left_click_object(Xvi_MainPage.move_Image_To_Show_inactive_treatments_CheckBox)
        self._show_inactive_treatments = value

    @property
    def show_inactive_fields(self):
        self._show_inactive_fields = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_fields_CheckBox).checked
        return self._show_inactive_fields

    @show_inactive_fields.setter
    def show_inactive_fields(self, value):
        isInactiveChecked = squishtest.waitForObject(Xvi_MainPage.move_Image_To_Show_inactive_fields_CheckBox).checked
        if isInactiveChecked != value:
            common.left_click_object(Xvi_MainPage.move_Image_To_Show_inactive_fields_CheckBox)
        self._show_inactive_fields = value

    @log_decorator
    def click_OK_button(self):
            common.left_click_object(Xvi_MainPage.move_Image_OK_Button)

    @log_decorator
    def click_Cancel_button(self):
            common.left_click_object(Xvi_MainPage.move_Image_Cancel_Button)

    @log_decorator
    def click_Help_button(self):
        if squishtest.waitForObjectItem(Xvi_MainPage.move_Image_Help_Button, "enabled", True):
            common.left_click_object(Xvi_MainPage.move_Image_Help_Button)